-- 카탈로그에 대응이 없는 seed 작품 45개를 목록에서 숨긴다(지우지 않음).
UPDATE pieces piece
SET piece.hidden_reason = 'catalog_unmatched'
WHERE piece.composer_id = 22 AND piece.origin = 'seed' AND piece.hidden_reason IS NULL
  AND piece.id IN (
    12029, 12039, 12076, 12085, 12149, 12169, 12400, 12445, 12480, 12502, 12518, 12539, 12543, 12555, 12556, 12657, 12685, 12728, 12791, 12827,
    12886, 12910, 12924, 12927, 12976, 13166, 13191, 13200, 13249, 13269, 13270, 13298, 13324, 13337, 13364, 13370, 13390, 13415, 13497, 13521,
    13539, 13569, 13585, 13670, 13722
  )
  AND NOT EXISTS (SELECT 1 FROM performance_sectors sector WHERE sector.piece_id = piece.id)
  AND NOT EXISTS (SELECT 1 FROM piece_parts linking WHERE linking.linked_piece_id = piece.id);
